using System.IO.Pipes;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Diagnostics;
using System.Text.Json;
namespace Nexora.Remote;

public sealed class SessionBroker : IRemoteDesktop
{
    NamedPipeServerStream? pipe; Process? worker; readonly SemaphoreSlim rpc = new(1, 1); readonly CancellationTokenSource stop = new(); readonly Task manager; uint leasedSession; long generation; volatile bool available; public bool Available => available && SessionLifecycle.Usable(leasedSession, generation); public CaptureTiming Timing { get; private set; } = new();
    public SessionBroker() { manager = Task.Run(() => Manage(stop.Token)); }
    public static PipeSecurity Security(SecurityIdentifier user) { var acl = new PipeSecurity(); acl.SetAccessRuleProtection(true, false); acl.AddAccessRule(new PipeAccessRule(new SecurityIdentifier(WellKnownSidType.NetworkSid, null), PipeAccessRights.FullControl, AccessControlType.Deny)); acl.AddAccessRule(new PipeAccessRule(new SecurityIdentifier(WellKnownSidType.LocalSystemSid, null), PipeAccessRights.FullControl, AccessControlType.Allow)); acl.AddAccessRule(new PipeAccessRule(user, PipeAccessRights.ReadWrite | PipeAccessRights.Synchronize, AccessControlType.Allow)); return acl; }
    async Task Manage(CancellationToken ct) { while (!ct.IsCancellationRequested) { uint session = NativeSession.WTSGetActiveConsoleSessionId(); if (session == uint.MaxValue || session == 0) { await Task.Delay(2000, ct); continue; } try { leasedSession = session; generation = SessionLifecycle.Generation(session); if (!SessionLifecycle.Usable(session, generation)) { await Task.Delay(1000, ct); continue; } var user = NativeSession.UserForSession(session); string name = "NexoraRemote-" + Guid.NewGuid().ToString("N"); pipe = NamedPipeServerStreamAcl.Create(name, PipeDirection.InOut, 1, PipeTransmissionMode.Byte, PipeOptions.Asynchronous | PipeOptions.FirstPipeInstance, 65536, 65536, Security(user)); var launched = NativeSession.Launch(session, name); worker = launched.Process; using var timeout = CancellationTokenSource.CreateLinkedTokenSource(ct); timeout.CancelAfter(15000); await pipe.WaitForConnectionAsync(timeout.Token); if (!Ipc.MatchesClient(pipe, worker.Id)) throw new UnauthorizedAccessException("Wrong IPC client process"); while (!ct.IsCancellationRequested && !worker.HasExited && NativeSession.WTSGetActiveConsoleSessionId() == session && SessionLifecycle.Usable(session, generation)) { if (NativeSession.UserForSession(session) != user) break; var result = await Call(new { type = "status" }, ct); available = result.GetProperty("available").GetBoolean(); await Task.Delay(2000, ct); } } catch (OperationCanceledException) when (ct.IsCancellationRequested) { break; } catch (Exception ex) { AgentLog.Write("worker.lifecycle", ex.GetType().Name); } finally { available = false; await rpc.WaitAsync(CancellationToken.None); try { pipe?.Dispose(); pipe = null; } finally { rpc.Release(); } if (worker is { HasExited: false }) { try { if (!worker.WaitForExit(1500)) worker.Kill(); } catch { } } worker?.Dispose(); worker = null; } await Task.Delay(2000, ct); } }
    async Task<JsonElement> Call(object message, CancellationToken ct) { using var timeout = CancellationTokenSource.CreateLinkedTokenSource(ct); timeout.CancelAfter(3000); await rpc.WaitAsync(timeout.Token); try { var p = pipe; if (p is null || !p.IsConnected) throw new IOException("No interactive worker"); await Ipc.Write(p, message, timeout.Token); var response = await Ipc.Read(p, timeout.Token); if (!response.GetProperty("ok").GetBoolean()) throw new UnauthorizedAccessException("Worker rejected operation"); return response; } finally { rpc.Release(); } }
    public async Task Authorize(string signed, Identity identity, CancellationToken ct) { await Call(new { type = "grant", grant = signed, identity = new Identity(identity.Server, identity.OrganizationId, identity.DeviceId, "", identity.ServerPublicKey) }, ct); }
    public async Task Revoke(CancellationToken ct) { if (pipe?.IsConnected == true) await Call(new { type = "revoke" }, ct); }
    public async Task Apply(JsonElement input, CancellationToken ct) { await Call(new { type = "input", input }, ct); }
    public async Task<byte[]?> Capture(CaptureOptions options, CancellationToken ct) { if (!Available) return null; var result = await Call(new { type = "capture", options }, ct); if (result.TryGetProperty("timing", out var timing)) Timing = timing.Deserialize<CaptureTiming>() ?? new(); return result.TryGetProperty("jpeg", out var jpeg) && jpeg.ValueKind == JsonValueKind.String ? Convert.FromBase64String(jpeg.GetString()!) : null; }
    public void Dispose() { stop.Cancel(); pipe?.Dispose(); try { manager.GetAwaiter().GetResult(); } catch (OperationCanceledException) { } stop.Dispose(); rpc.Dispose(); }
}
